//! Parses real encoder output from `target/fixtures` (generated by ffmpeg; see crates/dvd/tests).
//! Skipped when the fixtures are absent, e.g. on CI runners without ffmpeg.

use disccraft_psmux::es::ac3::parse_ac3;
use disccraft_psmux::es::mpeg2v::{PictureType, parse_video};
use disccraft_psmux::es::wav::parse_wav;
use disccraft_psmux::mux::{AudioSource, MuxInput, mux_vobs};
use disccraft_psmux::sink::MemorySink;
use std::path::PathBuf;

fn fixture(name: &str) -> Option<Vec<u8>> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../target/fixtures")
        .join(name);
    match std::fs::read(&path) {
        Ok(data) => Some(data),
        Err(_) => {
            eprintln!("skipped: {} not found", path.display());
            None
        }
    }
}

#[test]
fn ffmpeg_mpeg2_video() {
    let Some(data) = fixture("ntsc.m2v") else {
        return;
    };
    let video = parse_video(&data, 8_100_000).unwrap();
    assert_eq!((video.sequence.width, video.sequence.height), (720, 480));
    assert_eq!(video.sequence.frame_rate_code, 4);
    assert_eq!(video.sequence.aspect_code, 2);
    // 20 s at 29.97 fps.
    assert!(
        (599..=601).contains(&video.pictures.len()),
        "{}",
        video.pictures.len()
    );
    let first = &video.pictures[0];
    assert!(first.gop_start && first.closed_gop && first.has_sequence_header);
    assert_eq!(first.kind, PictureType::I);
    // Access units tile the stream.
    let mut end = 0;
    for p in &video.pictures {
        assert_eq!(p.offset, end);
        end = p.offset + p.len;
        assert!(p.pts >= p.dts);
    }
    assert_eq!(end, data.len());
    // Display timestamps are a permutation of evenly spaced frames.
    let mut pts: Vec<i64> = video.pictures.iter().map(|p| p.pts).collect();
    pts.sort_unstable();
    for w in pts.windows(2) {
        assert_eq!(w[1] - w[0], 900_900);
    }
}

#[test]
fn ffmpeg_ac3() {
    let Some(data) = fixture("ntsc.ac3") else {
        return;
    };
    let ac3 = parse_ac3(&data, 0).unwrap();
    assert_eq!(ac3.sample_rate, 48_000);
    assert_eq!(ac3.bit_rate_kbps, 192);
    assert_eq!(ac3.channels, 2);
    assert_eq!(ac3.frames.len() * 768, data.len());
}

#[test]
fn ffmpeg_wav() {
    let Some(data) = fixture("ntsc.wav") else {
        return;
    };
    let lpcm = parse_wav(&data).unwrap();
    assert_eq!(
        (lpcm.sample_rate, lpcm.channels, lpcm.bits),
        (48_000, 2, 16)
    );
    assert_eq!(lpcm.frame_bytes, 320);
    // 20 s of stereo 16-bit samples.
    assert_eq!(lpcm.data.len(), 20 * 48_000 * 4);
}

/// Muxes the ffmpeg fixtures into `target/fixtures/mux_test.vob` for inspection with ffprobe.
#[test]
fn ffmpeg_mux_vob() {
    let (Some(v), Some(a)) = (fixture("ntsc.m2v"), fixture("ntsc.ac3")) else {
        return;
    };
    let video = parse_video(&v, 8_100_000).unwrap();
    let first_pts = video.pictures.iter().map(|p| p.pts).min().unwrap();
    let ac3 = parse_ac3(&a, first_pts).unwrap();
    let input = MuxInput {
        video: &video,
        video_data: &v,
        audio: vec![AudioSource::Ac3 {
            stream: &ac3,
            data: &a,
        }],
        audio_start_pts: first_pts,
        cell_starts: vec![0, 5 * 27_000_000, 10 * 27_000_000],
        vob_id: 1,
        ntsc: true,
        subpictures: Vec::new(),
    };
    let mut sink = MemorySink {
        sectors: Vec::new(),
    };
    let layout = mux_vobs(&input, &mut sink).unwrap();
    assert_eq!(layout.cells.len(), 3);
    assert_eq!(layout.total_sectors as usize, sink.sectors.len());
    let out: Vec<u8> = sink.sectors.concat();
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../target/fixtures/mux_test.vob");
    std::fs::write(path, out).unwrap();
}

/// Muxes `still.m2v` (from `cargo run -p disccraft-mpeg2venc --example still_m2v`) with a highlight subpicture and three buttons into
/// `target/fixtures/menu_test.vob` for inspection with ffprobe.
#[test]
fn ffmpeg_menu_vob() {
    use disccraft_psmux::mux::hli::{Hli, HliButton, read_hli};
    use disccraft_psmux::mux::menu::{MenuVobInput, mux_menu_vob};
    use disccraft_spu::{Bitmap, SpuParams, encode_spu};

    let Some(v) = fixture("still.m2v") else {
        return;
    };
    let video = parse_video(&v, 8_100_000).unwrap();
    // 400×184 highlight area at (160, 120): a 4-px frame around each of three 48-px buttons.
    let (w, h) = (400usize, 184usize);
    let mut pixels = vec![0u8; w * h];
    for b in 0..3 {
        for y in b * 64..b * 64 + 48 {
            for x in 0..w {
                let edge = x < 4 || x >= w - 4 || y < b * 64 + 4 || y >= b * 64 + 44;
                if edge {
                    pixels[y * w + x] = 1;
                }
            }
        }
    }
    let bitmap = Bitmap {
        width: w as u16,
        height: h as u16,
        pixels,
    };
    let params = SpuParams {
        x: 160,
        y: 120,
        colors: [0, 1, 2, 3],
        alpha: [0, 15, 0, 0],
        forced: true,
        stop_delay: None,
    };
    let spu = encode_spu(&bitmap, &params).unwrap();
    let buttons: Vec<HliButton> = (0..3u16)
        .map(|b| HliButton {
            x1: 160,
            y1: 120 + b * 64,
            x2: 559,
            y2: 167 + b * 64,
            color_set: 1,
            auto_action: false,
            up: if b == 0 { 3 } else { b as u8 },
            down: if b == 2 { 1 } else { b as u8 + 2 },
            left: b as u8 + 1,
            right: b as u8 + 1,
            command: [0x30, 0x02, 0, 0, 0, 1, 0, 0],
        })
        .collect();
    let hli = Hli {
        start_ptm: 0,
        buttons,
        default_button: 1,
        button_offset: 0,
        color_sets: [[0x10, 0x00, 0xF0, 0x00, 0x20, 0x00, 0xF0, 0x00]; 3],
    };
    let input = MenuVobInput {
        video: &video,
        video_data: &v,
        spu: &spu,
        hli: &hli,
        vob_id: 1,
        ntsc: true,
        first_sector: 0,
    };
    let mut sink = MemorySink {
        sectors: Vec::new(),
    };
    let layout = mux_menu_vob(&input, &mut sink).unwrap();
    assert_eq!(layout.sectors as usize, sink.sectors.len());
    let nav = &sink.sectors[0];
    let got = read_hli(&nav[45..45 + 979]).unwrap().unwrap();
    assert_eq!(got.buttons.len(), 3);
    let path =
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../target/fixtures/menu_test.vob");
    std::fs::write(path, sink.sectors.concat()).unwrap();
}
